import{_ as o,o as a,c as s,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Libros de hechizos, pergaminos y reactivos","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/magic/spellbooks-scrolls-and-reagents.md","filePath":"es/guide/magic/spellbooks-scrolls-and-reagents.md"}'),r={name:"es/guide/magic/spellbooks-scrolls-and-reagents.md"};function i(t,e,l,c,d,m){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="spellbooks-scrolls-and-reagents" tabindex="-1">Libros de hechizos, pergaminos y reactivos <a class="header-anchor" href="#spellbooks-scrolls-and-reagents" aria-label="Enlace permanente a &quot;Libros de hechizos, pergaminos y reactivos&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> <strong>Implementación:</strong> no se ha establecido que este rediseño esté implementado. <strong>Disponibilidad:</strong> no se ha establecido que esté disponible en juego. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-09 respecto al Batch 04.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>El conocimiento debería persistir, mientras los grimorios raros, pergaminos y reactivos siguen siendo recursos físicos expuestos al riesgo.</li><li>Los pergaminos ofrecen acceso táctico consumible, no aprendizaje permanente.</li><li>La protección del libro personal, las ventajas de consulta y las reglas de consumo siguen sin resolverse.</li></ul><p><a href="/Syrolands-Public/es/game-design/magic/spellbooks-scrolls-and-reagents.html">Especificación completa del diseño</a></p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Función / límite Propuesto</th></tr></thead><tbody><tr><td>Conocimiento y libro personales</td><td>El conocimiento mágico aprendido debería quedarse con el personaje. El libro personal básico normalmente no debería caer como botín, pero su mecanismo exacto de sustitución/protección sigue sin decidirse. Esto no es un seguro general para objetos.</td></tr><tr><td>Libros físicos raros</td><td>Los grimorios y manuscritos físicos raros son distintos: pueden contener conocimiento valioso, anotaciones o ventajas de consulta y pueden ser saqueables. Un mejor índice podría ayudarte a consultar un patrón no memorizado; un libro raro no es simplemente una bonificación fija a Magery.</td></tr><tr><td>Pergaminos de lanzamiento</td><td>Los pergaminos son consumibles físicos y generalmente caen al morir. Pueden proporcionar acceso temporal o una variante preparada y podrían acortar la consulta de un hechizo no memorizado. Un pergamino de Dispel para emergencias ilustra su valor táctico a un coste consumible. Los pergaminos de lanzamiento ordinarios no enseñan permanentemente; los artefactos diseñados específicamente para enseñar siguen siendo una pregunta abierta.</td></tr><tr><td>Reactivos</td><td>Los reactivos siguen siendo recursos físicos expuestos al riesgo que generalmente caen al morir. Catalizadores, estabilizadores y otros materiales pueden apoyar patrones y variantes, con procesamiento mediante Alchemy y conexiones con Inscription. Ninguna receta, sustitución o regla de consumo en caso de fallo es definitiva.</td></tr></tbody></table><p><a href="/Syrolands-Public/es/guide/professions/inscription.html">Inscription</a> · <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria</a>.</p>',8)])])}const g=o(r,[["render",i]]);export{u as __pageData,g as default};
